function calculateArea(width, widthUnit, height, heightUnit) {
  const convertToMeters = (value, unit) => {
    if (unit === 'ft') {
      return value * 0.3048; // 1 foot = 0.3048 meters
    } else if (unit === 'm') {
      return value;
