### Solution:
```rust
struct Curry<F> {
    fun: F,
}

impl<F> Curry<F> {
    fn new(fun: F) -> Self {
        Curry { fun }
    }
}

impl<F, A> FnOnce<(A,)> for Curry<F>
where
    F: Fn(A) -> Vec<String>,
{
    type Output = Vec<String>;

    extern "rust-call" fn call_once(self, args: (A,)) -> Self::Output {
        (self.fun)(args.0)
    }
}

impl<F, A> FnOnce<(A,)> for &Curry<F>
where
    F: Fn(A) -> Vec<String>,
{
