### Problem:
You are given a JavaScript object representing a nested data structure. Your task is to write a function that flattens this object into a single-level object, where the keys are the concatenated keys from the original object and the values are the corresponding leaf nodes.

For example, given the following input object:
```javascript
const inputObject = {
  key1: {
    key2: {
      key3: 'value1',
      key4: 'value2',
    },
    key5: 'value3',
  },
  key6: 'value4',
};
```
The expected output after flattening the object would be:
```javascript
{
  'key1.key2.key3': 'value1',
  'key1.key2.key4': 'value2',
  'key1.key5': 'value3',
  'key6': 'value4',
}
```
Write a function `flattenObject(obj)` that takes the input object `obj` and returns the flattened object as described above.

### Solution:
```javascript
function flattenObject(obj) {
  const result = {};

  function recurse(curr, prop) {
    if (Object(curr) !== curr) {
      result[prop] = curr;
    } else if (Array.isArray(curr)) {
      for (let i = 0, l = curr.length; i < l; i++) {
        recurse(curr[i], prop + '[' + i + ']');
      }
      if (l == 0) {
        result[prop] = [];
      }
    } else {
      let isEmpty = true;
      for (let p in curr) {
        isEmpty = false;
        recurse(curr[p], prop ? prop + '.' + p : p);
      }
      if (isEmpty && prop) {
        result[prop] = {};
      }
    }
  }

  recurse(obj, '');
  return result;
}

const inputObject = {
  key1: {
    key2: {
      key3: 'value1',
      key4: 'value2',
    },
    key5: 'value3',
  },
  key6: 'value4',
};

const flattenedObject = flattenObject(inputObject);
console.log(flattenedObject);
```

