use rand::Rng;
use std::io;

fn get_player_choice() -> String {
    loop {
        println!("Enter your choice (rock, paper, scissors) or 'quit' to exit:");
        let mut input = String::new();
        io::stdin().read_line(&mut input).expect("Failed to read line");
        let input = input.trim().to_lowercase();
        if input == "rock" || input == "paper" || input == "scissors" || input == "quit" {
            return input;
        } else {
            println!("Invalid choice. Please enter rock, paper, or scissors.");
        }
    }
}

fn get_computer_choice() -> String {
