struct Rectangle {
    let x: Int
    let y: Int
    let width: Int
    let height: Int
}

func rect(forPosition position: Position, size: (width: Int, height: Int)) -> Rectangle {
    let rectSize = (width: 3, height: 3)

    switch position {
    case .topLeft:
        return Rectangle(x: 0, y: 0, width: rectSize.width, height: rectSize.height)
    case .topRight:
        return Rectangle(x: size.width - rectSize.width, y: 0, width: rectSize.width, height: rectSize.height)
