use std::io::Error;

#[derive(Debug, PartialEq)]
struct Interactive {
    throttle: u8,
    roll: u8,
    pitch: u8,
    yaw: u8,
}

fn to_vec(interactive: &Interactive) -> Result<Vec<u8>, Error> {
    let mut output = Vec::with_capacity(4);
    output.push(interactive.throttle);
    output.push(interactive.roll);
    output.push(interactive.pitch);
    output.push(interactive.yaw);
