  const command = `react-native run-ios --configuration=${configuration} --simulator "${simulator}"`;

  exec(command, (error, stdout, stderr) => {
    if (error) {
      console.error(`Error launching app: ${error.message}`);
      return;
    }
    if (stderr) {
      console.error(`Error launching app: ${stderr}`);
      return;
