    let unexpected_token = Token {
        lexeme: "}".to_string(),
        pos: 10,
    };
    let expected_token = Token {
        lexeme: "{".to_string(),
        pos: 8,
    };
    let parse_error1 = ParseError::UnexpectedToken {
        unexpected: unexpected_token,
        expected: Some(expected_token),
        msg: "Expected '{'".to_string(),
    };
    let parse_error2 = ParseError::MissingToken {
        expected: Token {
            lexeme: "(".to_string(),
            pos: 15,
        },
    };

