public String parseSearchQuery(String input) {
    int start = input.indexOf("\"");
    if (start == -1) {
        return "";
    }
    int end = input.indexOf("\"", start + 1);
    if (end == -1) {
        return "";
    }
    return input.substring(start + 1, end);
}
```

