    // Your code here
}
```

For example, given the input:
```
test_literal!(1.0);
test_literal!("hello");
test_literal!(42);
```
The function should return `["1.0", "hello", "42"]`.

Assume that the input `test_cases` will always be non-empty and well-formatted, containing at least one test case.

### Solution:
```rust
fn process_test_cases(test_cases: &str) -> Vec<String> {
    let mut extracted_values = Vec::new();
    for line in test_cases.lines() {
        if let Some(start) = line.find('!') {
            if let Some(end) = line.find(';') {
                let value = line[start + 1..end].trim();
                extracted_values.push(value.to_string());
            }
        }
    }
    extracted_values
}
