let package = Package(
  name: "Nakama",
  platforms: [
      .macOS(.v10_15), .iOS(.v13), .tvOS(.v13), .watchOS(.v6)
  ],
  // ...
)
"""

let result = parsePackageManifest(packageManifest)
print(result)  // Output: ["macOS": "10.15", "iOS": "13", "tvOS": "13", "watchOS": "6"]
```

