    TwitObj(message: "Hello, this"),
    TwitObj(message: "is a test"),
    TwitObj(message: "message for"),
    TwitObj(message: "Twit_Split!"),
    TwitObj(message: "This is"),
    TwitObj(message: "another"),
    TwitObj(message: "test"),
    TwitObj(message: "message."),
    TwitObj(message: "A short"),
    TwitObj(message: "message.")
]
```

