### Solution:
```swift
extension Array where Element == TwitObj {
    func splitMessages(maxLength: Int) -> [TwitObj] {
        var splitTwitObjs: [TwitObj] = []

        for twitObj in self {
            let words = twitObj.message.components(separatedBy: " ")
            var currentMessage = ""

            for word in words {
                if currentMessage.isEmpty {
                    currentMessage = word
                } else if currentMessage.count + word.count + 1 <= maxLength {
                    currentMessage += " " + word
                } else {
                    splitTwitObjs.append(TwitObj(message: currentMessage))
                    currentMessage = word
                }
            }

            if !currentMessage.isEmpty {
                splitTwitObjs.append(TwitObj(message: currentMessage))
            }
        }

        return splitTwitObjs
    }
}
```

