Your module should have the following methods:
1. `setCookie(name, value, days)`: This method should set a cookie with the given name, value, and expiration days.
2. `getCookie(name)`: This method should return the value of the cookie with the given name, or null if the cookie does not exist.
3. `deleteCookie(name)`: This method should delete the cookie with the given name.

You should also create a simple HTML page that includes the necessary JavaScript code to demonstrate the usage of your cookie management module.

Create a JavaScript module for cookie management and demonstrate its usage in an HTML page.

### Solution:
```javascript
// Cookie management module
var CookieManager = (function() {
  function setCookie(name, value, days) {
    var expires = "";
    if (days) {
      var date = new Date();
      date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
      expires = "; expires=" + date.toUTCString();
    }
    document.cookie = name + "=" + value + expires + "; path=/";
  }

  function getCookie(name) {
    var nameEQ = name + "=";
    var cookies = document.cookie.split(';');
    for (var i = 0; i < cookies.length; i++) {
      var cookie = cookies[i];
      while (cookie.charAt(0) == ' ') {
        cookie = cookie.substring(1, cookie.length);
      }
      if (cookie.indexOf(nameEQ) == 0) {
        return cookie.substring(nameEQ.length, cookie.length);
      }
    }
    return null;
  }

  function deleteCookie(name) {
    document.cookie = name + "=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;";
  }

  return {
    setCookie: setCookie,
    getCookie: getCookie,
    deleteCookie: deleteCookie
  };
})();

