```php
function parseQueryConditions($codeSnippet) {
    $conditions = [];
    $lines = explode("\n", $codeSnippet);
    foreach ($lines as $line) {
        if (strpos($line, '->where') !== false || strpos($line, '->orWhere') !== false) {
            $parts = explode(',', $line);
            $field = trim(substr($parts[0], strpos($parts[0], "'") + 1, strrpos($parts[0], "'") - strpos($parts[0], "'") - 1));
            $operator = trim(substr($parts[1], strpos($parts[1], "'") + 1, strrpos($parts[1], "'") - strpos($parts[1], "'") - 1));
            $value = trim(substr($parts[2], strpos($parts[2], "'") + 1, strrpos($parts[2], "'") - strpos($parts[2], "'") - 1));
            $conditions[] = [
                'field' => $field,
                'operator' => $operator,
                'value' => $value
            ];
        }
    }
    return $conditions;
}
```

