### Solution:
```go
package main

import (
	"fmt"
	"os"
	"os/exec"
	"strings"
)

func main() {
	if len(os.Args) < 2 {
		fmt.Println("Usage: go run main.go <directory_path>")
		return
	}

	directoryPath := os.Args[1]

	cmd := exec.Command("grep", "-r", "ioutil", "-I", "--include=*.go", "--exclude", "stdlib.go", directoryPath)
	output, err := cmd.CombinedOutput()

	if err != nil {
		fmt.Println("Error occurred while executing grep command:", err)
		return
	}

