### Solution:
```rust
use bio::io::fasta;
use bio::alphabets::dna;
use bio::seq::translate;

fn main() {
    // Define the frames for translation
    let frames = vec![
        ("Frame1", 0, false),
        ("Frame2", 1, false),
        ("Frame3", 2, false),
        ("RevFrame1", 0, true),
        ("RevFrame2", 1, true),
        ("RevFrame3", 2, true),
    ];

    // Read DNA sequences in FASTA format from standard input
    for record in fasta::Reader::new(std::io::stdin(), true).records() {
        let fasta::Record { header, sequence } = record.expect("Error reading record");

        // Convert the DNA sequence into a forward strand
        let forward = dna::RevComp::new(&sequence);

        // Create a reverse strand by reversing the nucleotide sequence
        let reverse = dna::RevComp::new(&sequence).rev_comp();

        // Translate the DNA sequence into amino acid sequences for different reading frames and strands
        for &(name, frame, reversed) in &frames {
            let strand = if reversed { &reverse } else { &forward };
            let translation = translate(strand, frame, Some(&dna::STANDARD));
            println!("Header: {}", header);
            println!("Frame: {} - Reversed: {}", name, reversed);
            println!("Translation: {:?}", translation);
        }
    }
}
