    // Transition from Init to Established
    match state {
        ProtocolState::Init => {
            state = ProtocolState::Established;
            assert_req_sent!(state);
        }
        _ => panic!("Invalid state transition"),
    }

    // Transition from Established to Closed
    match state {
        ProtocolState::Established => {
            state = ProtocolState::Closed;
            assert_closed!(state);
        }
        _ => panic!("Invalid state transition"),
    }

    // Transition from Closed to Init
