      Object value = field.get(param);
      if (value instanceof String) {
        String stringValue = (String) value;
        int minSize = sizeField.min();
        int maxSize = sizeField.max();
        if (stringValue.length() < minSize || stringValue.length() > maxSize) {
          return resultHelper.infoResp(ErrorType.SYS0003, sizeField.message(), HttpStatus.UNPROCESSABLE_ENTITY);
        }
      } else if (value instanceof Collection) {
        Collection<?> collectionValue = (Collection<?>) value;
        int minSize = sizeField.min();
        int maxSize = sizeField.max();
        if (collectionValue.size() < minSize || collectionValue.size() > maxSize) {
          return resultHelper.infoResp(ErrorType.SYS0003, sizeField.message(), HttpStatus.UNPROCESSABLE_ENTITY);
        }
      }
      // Additional logic for other types if needed
    }
  }
  return resultHelper.successResp(param);
}
