function deleteTrainingFiles($training)
{
    // Extract the filename from the training's link_training attribute
    $filename = explode(".", $training->link_training)[0];

    // Define the directory where the training files are stored
    $directory = FCPATH . "uploads/trainings/";

    // Use glob to find all files associated with the filename
    $filesToDelete = glob($directory . $filename . ".*");

    // Check if any files are found
    if ($filesToDelete !== false) {
        // Use array_map in combination with unlink to delete all the found files
        $result = array_map('unlink', $filesToDelete);

