  HttpClientModule,
  // import LeafletMap from 'leaflet';
  /*
  import { LeafletMap } from 'leaflet';
  */
  \`import { LeafletMap } from 'leaflet';\`
]
`;
console.log(countImports(fileContent)); // Output: 2
```

