### Problem:
You are tasked with implementing a simple shell program in Rust that supports executing commands, piping output between commands, and handling basic signal handling. The given code snippet provides the necessary system call macros for interacting with the operating system.

Your task is to implement the following functionalities in the shell program:
1. Execute a single command without any arguments.
2. Implement basic piping functionality to allow the output of one command to be used as input for another command.
3. Handle the SIGINT signal (Ctrl+C) to terminate the currently running command without exiting the shell.

You should use the provided system call macros to interact with the operating system for forking processes, executing commands, piping, and signal handling.

Your implementation should handle errors gracefully and provide appropriate error messages when necessary.

### Solution:
```rust
use std::process::Command;
use std::os::unix::process::CommandExt;
use std::ptr;
use std::ffi::CString;
use std::io::{self, Write};
use std::process;
use libc;

fn main() {
    loop {
        print!("> ");
        io::stdout().flush().unwrap();

        let mut input = String::new();
        io::stdin().read_line(&mut input).unwrap();

        let input = input.trim();

        if input.is_empty() {
            continue;
        }

        let commands: Vec<&str> = input.split('|').map(|c| c.trim()).collect();

        if commands.len() == 1 {
            execute_command(commands[0]);
        } else {
            execute_piped_commands(commands);
        }
    }
}

fn execute_command(command: &str) {
    let args: Vec<&str> = command.split_whitespace().collect();
    let program = CString::new(args[0]).unwrap();
    let args: Vec<CString> = args.iter().map(|&arg| CString::new(arg).unwrap()).collect();

    unsafe {
        match libc::fork() {
            -1 => {
                eprintln!("Fork failed");
                process::exit(1);
            }
            0 => {
                // Child process
                let res = libc::execvp(program.as_ptr(), args.as_ptr());
                if res == -1 {
                    eprintln!("Failed to execute command");
                    process::exit(1);
                }
            }
            _ => {
                // Parent process
                libc::wait(ptr::null_mut());
            }
        }
    }
}

fn execute_piped_commands(commands: Vec<&str>) {
    let mut pipes: Vec<i32> = Vec::new();

    for _ in 0..commands.len() - 1 {
        let mut pipe_fd: [i32; 2] = [0; 2];
        unsafe {
            if libc::pipe(pipe_fd.as_mut_ptr()) == -1 {
                eprintln!("Pipe creation failed");
                process::exit(1);
            }
        }
        pipes.push(pipe_fd[0]);
        pipes.push(pipe_fd[1]);
    }

    for (i, command) in commands.iter().enumerate() {
        let args: Vec<&str> = command.split_whitespace().collect();
        let program = CString::new(args[0]).unwrap();
        let args: Vec<CString> = args.iter().map(|&arg| CString::new(arg).unwrap()).collect();

        unsafe {
            match libc::fork() {
                -1 => {
                    eprintln!("Fork failed");
                    process::exit(1);
                }
                0 => {
                    // Child process
                    if i != 0 {
                        libc::dup2(pipes[(i - 1) * 2], libc::STDIN_FILENO);
                    }
                    if i != commands.len() - 1 {
                        libc::dup2(pipes[i * 2 + 1], libc::STDOUT_FILENO);
                    }

                    for j in 0..pipes.len() {
                        libc::close(pipes[j]);
                    }

                    let res = libc::execvp(program.as_ptr(), args.as_ptr());
                    if res == -1 {
                        eprintln!("Failed to execute command");
                        process::exit(1);
                    }
                }
                _ => {
                    // Parent process
                }
            }
        }
    }

    for pipe_fd in pipes {
        unsafe {
            libc::close(pipe_fd);
        }
    }

    for _ in 0..commands.len() {
        unsafe {
            libc::wait(ptr::null_mut());
        }
    }
}

extern "C" fn handle_sigint(_: libc::c_int) {
    println!("Received SIGINT");
}

fn setup_signal_handler() {
    unsafe {
        libc::signal(libc::SIGINT, handle_sigint as usize);
    }
}

fn main() {
    setup_signal_handler();
    // ... rest of the main function as provided in the previous solution
}
```

