Your implementation should be efficient and handle edge cases appropriately.

### Solution:
```swift
struct CodingKeyMapping {
    private var keys: Set<String> = []

    mutating func addKey(key: String) {
        keys.insert(key)
    }

    mutating func removeKey(key: String) {
        keys.remove(key)
    }

    func encode(data: [String: Any]) -> [String: Any] {
        var encodedData: [String: Any] = [:]
        for (key, value) in data {
            if keys.contains(key) {
                if let codingKey = CodingKeys(rawValue: key) {
                    encodedData[codingKey.rawValue] = value
                }
            }
        }
        return encodedData
    }

    func decode(data: [String: Any]) -> [String: Any] {
        var decodedData: [String: Any] = [:]
        for (key, value) in data {
            if let codingKey = CodingKeys(rawValue: key) {
                decodedData[codingKey.rawValue] = value
            }
        }
        return decodedData
    }
}

private enum CodingKeys: String, CodingKey {
    case recordType = "record_type",
         id,
         tooltip,
         description,
         date = "start_date"
}
```

