### Solution:
```typescript
import pako from 'pako'; // Using pako library for gzip decompression

export function decompress(arr: Uint8Array, max_uncompressed_size: number): Promise<Uint8Array> {
  return new Promise((resolve, reject) => {
    try {
      const uncompressedData = pako.inflate(arr); // Using pako library to decompress the input data
      if (uncompressedData.length > max_uncompressed_size) {
        reject(new Error('Uncompressed data exceeds the specified max size'));
      } else {
