### Solution:
```javascript
const fetch = require('node-fetch'); // Assuming the use of node-fetch for making HTTP requests

function fetchDataFromURL(url) {
  return new Promise((resolve, reject) => {
    fetch(url)
      .then(response => {
        if (response.ok) {
          resolve(response.json());
        } else {
          reject(`Error fetching data from ${url}: ${response.status} ${response.statusText}`);
        }
      })
      .catch(error => {
        reject(`Error fetching data from ${url}: ${error.message}`);
      });
  });
}
