### Solution:
```swift
struct CustomArray<T> {
    private var elements: [T]

    init(_ elements: [T]) {
        self.elements = elements
    }

    func prettyDescription() -> String {
        var output: [String] = ["\n["]
        for (index, element) in elements.enumerated() {
            output.append("\t\(index): \(element)")
        }
        output.append("]\n")
        return output.joined(separator: "\n")
    }
}

