use rand::Rng;

fn rock_paper_scissors(user_choice: &str) -> String {
    let choices = ["rock", "paper", "scissors"];
    let computer_choice = choices[rand::thread_rng().gen_range(0..3)];

    match (user_choice, computer_choice) {
        ("rock", "scissors") | ("paper", "rock") | ("scissors", "paper") => {
            format!("You win! {} beats {}", user_choice, computer_choice)
        }
        ("rock", "paper") | ("paper", "scissors") | ("scissors", "rock") => {
            format!("You lose! {} beats {}", computer_choice, user_choice)
        }
        _ => format!("It's a draw! Both chose {}", user_choice),
    }
}

fn main() {
    let user_choice = "rock";
    println!("User's choice: {}", user_choice);
    let result = rock_paper_scissors(user_choice);
    println!("Outcome: {}", result);
}
```

In this solution, the `rock_paper_scissors` function takes the user's choice as input, generates a random choice for the computer, compares the choices, and returns the outcome of the game based on the standard rules of rock-paper-scissors. The `main` function demonstrates the usage of the `rock_paper_scissors` function by providing a user's choice and printing the outcome of the game.

