  input: 'font-size: 2em; width: 90%;',
  button: 'background-color: #008CBA; color: white;',
  textarea: ''
}
```

Ensure that the function handles cases where the CSS code contains comments, multiple selectors in a single rule, and other valid CSS syntax.

### Solution:
```javascript
function extractCSSRules(cssCode, selectors) {
  const cssRules = {};
  const regex = /([^{]+)\s*{([^}]+)}/g;
  let match;

  while ((match = regex.exec(cssCode)) !== null) {
    const selector = match[1].trim();
    const rules = match[2].trim();
    cssRules[selector] = rules;
  }

  const result = {};
  selectors.forEach(selector => {
    result[selector] = cssRules[selector] || '';
  });

  return result;
}

