// Implementation of the bind function
function bind(el, model) {
  // Update the text content of the HTML element with the value from the model
  el.textContent = model.value;

  // Create a proxy to observe changes in the model
  const handler = {
    set: function(obj, prop, value) {
      obj[prop] = value;
