pub async fn break_insert(&self, at: LineSpec) -> Result<Breakpoint, Error> {
    let raw = self
        .raw_cmd(format!("-break-insert {}", at.serialize()))
        .await?
        .expect_result()?
        .expect_payload()?
        .remove_expect("bkpt")?
        .expect_dict()?;

    let bkpt = raw.get("bkpt").ok_or(Error::ParseError("Breakpoint details not found"))?;
    let bkpt_dict = bkpt.expect_dict().ok_or(Error::ParseError("Breakpoint details not in dictionary format"))?;

    let id = bkpt_dict.get("number").and_then(|n| n.expect_u64()).ok_or(Error::ParseError("Breakpoint number not found"))?;
    let file = bkpt_dict.get("file").and_then(|f| f.expect_string()).ok_or(Error::ParseError("Breakpoint file not found"))?;
    let line = bkpt_dict.get("line").and_then(|l| l.expect_u64()).ok_or(Error::ParseError("Breakpoint line not found"))?;

    Ok(Breakpoint { id, file, line })
}
```

