  // Your implementation here
}
```

### Solution:
```javascript
function mergePermissions(...permissionObjects) {
  const mergedPermissions = {};
  for (const permissions of permissionObjects) {
    for (const variable in permissions) {
      if (permissions.hasOwnProperty(variable)) {
        mergedPermissions[variable] = permissions[variable];
      }
    }
  }
  return mergedPermissions;
}
