import UIKit

public extension DispatchQueue {

    // DispatchLevel: Enum for easier access to DispatchQueues types
    enum DispatchLevel {
        case main
        case userInteractive
        case userInitiated
        case utility
        case background
        case custom(queue: DispatchQueue)
    }

    // executeOn: Executes a closure on a specific dispatch queue
    func executeOn(_ level: DispatchLevel, closure: @escaping () -> Void) {
        switch level {
        case .main:
            DispatchQueue.main.async {
                closure()
            }
        case .userInteractive:
            DispatchQueue.global(qos: .userInteractive).async {
                closure()
            }
        case .userInitiated:
            DispatchQueue.global(qos: .userInitiated).async {
                closure()
            }
        case .utility:
            DispatchQueue.global(qos: .utility).async {
                closure()
            }
        case .background:
            DispatchQueue.global(qos: .background).async {
                closure()
            }
        case .custom(let queue):
            queue.async {
                closure()
            }
        }
    }
}

// Example usage
let customQueue = DispatchQueue(label: "com.example.customQueue")
customQueue.executeOn(.custom(queue: customQueue)) {
    print("Executing on custom queue")
}
```

In this solution, the DispatchQueue extension provides the executeOn method, which takes a DispatchLevel enum value and a closure. The method then dispatches the closure to the corresponding DispatchQueue type based on the provided DispatchLevel.

The example usage demonstrates how to use the custom DispatchQueue extension to execute a closure on a custom dispatch queue.

