        {
            for (int i = 0; i < expected.Count; i++)
            {
                elementAsserter(expected[i], actual[i]);
            }
        }
    }
    else
    {
        List<T> sortedExpected = expected.OrderBy(e => e).ToList();
        List<T> sortedActual = actual.OrderBy(e => e).ToList();

        if (elementAsserter == null)
        {
            for (int i = 0; i < sortedExpected.Count; i++)
