                {
                    throw new Exception($"Lists differ at index {i}: Expected {sortedExpected[i]}, Actual {sortedActual[i]}");
                }
            }
        }
        else
        {
            for (int i = 0; i < sortedExpected.Count; i++)
            {
                elementAsserter(sortedExpected[i], sortedActual[i]);
            }
        }
    }
}
```

