import { loadJsonFile } from 'load-json-file';

interface ProjectManifest {
  dependencies?: Record<string, string>;
}

interface Lockfile {
  specifiers: Record<string, string>;
  packages: Record<string, unknown>;
}

function validateDependenciesConsistency(projectDirectory: string): boolean {
  try {
    const manifest = await loadJsonFile<ProjectManifest>(`${projectDirectory}/package.json`);
    const lockfile = await loadJsonFile<Lockfile>(`${projectDirectory}/lockfile.json`);

    const expectedVersion = manifest.dependencies?.['peer-a'];
