public Color[,] ConvertToGrayscale(Color[,] originalImage)
{
    int width = originalImage.GetLength(0);
    int height = originalImage.GetLength(1);
    Color[,] result = new Color[width, height];

    for (int i = 0; i < width; ++i)
    {
        for (int j = 0; j < height; ++j)
        {
            Color pixelColor = originalImage[i, j];
            int grayscaleValue = (int)(0.2126 * pixelColor.R + 0.7152 * pixelColor.G + 0.0722 * pixelColor.B);
            result[i, j] = Color.FromArgb(grayscaleValue, grayscaleValue, grayscaleValue);
        }
    }

    return result;
}
```

The `ConvertToGrayscale` method takes the original image represented as a 2D array of colors and returns the processed image with the grayscale values. It iterates through each pixel in the original image, calculates the grayscale value using the luminance method, and updates the `result` array with the grayscale values. The grayscale value is then used to create a new grayscale color, which is assigned to the corresponding position in the `result` array. Finally, the processed image is returned.

