    let server = Server { resources: vec![] };
    let resource1 = Arc::new(MyResource {
        status: "active".to_string(),
    });
    let resource2 = Arc::new(MyResource {
        status: "inactive".to_string(),
    });
    server.add_resource(resource1.clone());
    server.add_resource(resource2.clone());

    // Query resources with a specific status
    let active_resources = server.get_resources_with_status("active");
    for resource in active_resources {
        println!("Active resource status: {}", resource.get_status());
    }
}
```

