function processFileNameAndPath($log_dir, $ResultFileNameStr, $fileExtension) {
    $aryFileName = getFileNameAndPath($log_dir, $ResultFileNameStr, $fileExtension);

    if (count($aryFileName) > 0) {
        $baseFileName = $ResultFileNameStr;
        $counter = 1;

        while (in_array($baseFileName . "_" . $counter . $fileExtension, $aryFileName)) {
            $counter++;
        }

        $modifiedFileName = ($counter > 1) ? $baseFileName . "_" . $counter : $baseFileName;
