    int inputSequence[] = {0, 1, 1, 0, 0, 1, 1, 1, 0};
    int sequenceLength = sizeof(inputSequence) / sizeof(inputSequence[0]);
    simulateInterrupt(inputSequence, sequenceLength);
    return 0;
}
```

