fn contains_non_ascii_byte_constants(source_code: &str) -> bool {
    let mut in_byte_constant = false;
    let mut in_escape_sequence = false;
    let mut non_ascii_found = false;

    for c in source_code.chars() {
        match c {
            'b' if !in_byte_constant => in_byte_constant = true,
            '\'' if in_byte_constant && !in_escape_sequence => in_byte_constant = false,
            '"' if in_byte_constant && !in_escape_sequence => in_byte_constant = false,
