```

### Solution:
```php
function validateYear($year): string {
    if (is_int($year) && $year > 0) {
        if (($year % 4 == 0 && $year % 100 != 0) || $year % 400 == 0) {
            return "$year is a valid leap year.";
        } else {
            return "$year is a valid year but not a leap year.";
        }
    } else {
        return "Invalid input: $year is not a valid year.";
    }
}
