use std::collections::HashMap;

type Key = u64;
type Value = String;

struct MessageStore {
    loaded: HashMap<Key, Value>,
}

impl Persist<Key, Value> for MessageStore {
    type Error = String;

    fn persist(&mut self, key: Key, value: Value) -> Result<(), Self::Error> {
        if self.loaded.contains_key(&key) {
            Err(format!("Key {:?} already exists", key))
        } else {
            self.loaded.insert(key, value);
            Ok(())
        }
    }

