    // Create a new empty stack
    fn new() -> Self {
        Stack { data: Vec::new() }
    }

    // Add an item to the top of the stack
    fn push(&mut self, item: T) {
        self.data.push(item);
    }

    // Remove and return the item at the top of the stack
    // If the stack is empty, return None
    fn pop(&mut self) -> Option<T> {
        self.data.pop()
    }

    // Return a reference to the item at the top of the stack without removing it
    // If the stack is empty, return None
    fn peek(&self) -> Option<&T> {
        self.data.last()
    }

    // Return true if the stack is empty, false otherwise
    fn is_empty(&self) -> bool {
        self.data.is_empty()
    }
}

fn main() {
    let mut stack = Stack::new();
    stack.push(1);
    stack.push(2);
    stack.push(3);

    println!("Peek: {:?}", stack.peek());  // Output: Peek: Some(3)
    println!("Pop: {:?}", stack.pop());    // Output: Pop: Some(3)
    println!("Pop: {:?}", stack.pop());    // Output: Pop: Some(2)
    println!("Is empty: {}", stack.is_empty());  // Output: Is empty: false
}
```

