function bulkClassifyUtterances(utterances, classificationRules) {
    const classificationResults = {};

    for (const utterance of utterances) {
        for (const rule of classificationRules) {
            for (const keyword of rule.keywords) {
                if (utterance.text.toLowerCase().includes(keyword.toLowerCase())) {
                    if (!classificationResults[rule.category]) {
                        classificationResults[rule.category] = [];
