use std::collections::HashMap;

#[derive(Debug)]
enum UsState {
    Alabama,
}

struct Inventory {
    items: HashMap<String, i32>,
}

impl Inventory {
    fn new() -> Inventory {
        Inventory {
            items: HashMap::new(),
        }
    }

    fn add_item(&mut self, item_name: String, quantity: i32) {
        let item_stock = self.items.entry(item_name).or_insert(0);
        *item_stock += quantity;
    }

