use crate::{Error, Result};

pub struct Delete {
    data: DeleteData,
    logger: Logger,
    tracer: Arc<opentracingrust::Tracer>,
}

impl Delete {
    pub fn new(logger: Logger, tracer: Arc<opentracingrust::Tracer>) -> Delete {
        Delete {
            data: DeleteData::default(),
            logger,
            tracer,
        }
    }

    pub fn delete_record(&self, record_id: u64) -> Result<(), Error> {
        self.logger.log("Starting deletion operation for record_id: {}", record_id);

