#include <vector>
#include <variant>

int nestedListSum(const std::variant<int, std::vector<std::variant<int, std::vector<int>>>>& nestedList) {
    int sum = 0;
    if (std::holds_alternative<int>(nestedList)) {
        sum += std::get<int>(nestedList);
    } else {
