### Solution:
```rust
use std::io;

#[derive(Debug, Default, Clone, Hash)]
pub struct MemReader {
    pos: usize,
    buf: Vec<u8>
}

impl io::Read for MemReader {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        let out_amount = self.buf.len() - self.pos;
        let in_space = buf.len();

        if out_amount == 0 {
            return Ok(0);
        }

        let to_copy = std::cmp::min(out_amount, in_space);
        buf[..to_copy].copy_from_slice(&self.buf[self.pos..self.pos + to_copy]);
        self.pos += to_copy;

        Ok(to_copy)
    }
}
```

In the `read` method, the code first checks if there is no more data to read from the buffer. If so, it returns 0. Otherwise, it calculates the number of bytes to copy based on the available space in the provided buffer and the remaining data in the buffer. It then copies the data from the buffer into the provided buffer slice, updates the position, and returns the number of bytes read.

