### Solution:
```swift
import XCTest

enum ElementStatus: String {
    case exist = "exists == true"
    case hittable = "isHittable == true"
    // Add more conditions as needed
}

func waitUntil(element: XCUIElement, condition: ElementStatus, timeout: TimeInterval = TimeInterval(5)) {
    let expectation = XCTNSPredicateExpectation(predicate: NSPredicate(format: condition.rawValue), object: element)
    let result = XCTWaiter().wait(for: [expectation], timeout: timeout)

    if result == .timedOut {
        XCTFail("Timed out waiting for \(condition.rawValue) for element: \(element)")
