func fetchFileContent(from fileName: String) -> String? {
    guard let fileURL = URL(string: fileName) else {
        return nil
    }

    do {
        let content = try String(contentsOf: fileURL, encoding: .utf8)
        return content
    } catch {
        return nil
    }
}

func saveDocumentationOutputFile(with content: String, documentName: String?, path: String?) {
    let fileManager = FileManager.default
    let documentFileName = documentName ?? "default_documentation.txt"
    let filePath = (path != nil) ? (path! as NSString).appendingPathComponent(documentFileName) : documentFileName

