func longestCommonPrefix(_ strs: [String]) -> String {
    guard !strs.isEmpty else { return "" }

    var prefix = strs[0]

    for i in 1..<strs.count {
        while !strs[i].hasPrefix(prefix) {
            prefix.removeLast()
            if prefix.isEmpty { return "" }
        }
    }

