use std::task::{Context, Poll};
use futures::stream::Stream;

struct CustomStream {
    // Fields and state for the custom stream
    sequence: Vec<i32>,
    current_index: usize,
}

impl Stream for CustomStream {
    type Item = i32;

    fn poll_next(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
        // Check if there are more elements in the sequence
        if self.current_index < self.sequence.len() {
            let next_value = self.sequence[self.current_index];
            self.current_index += 1;
            Poll::Ready(Some(next_value))
        } else {
            // No more elements in the sequence
            Poll::Ready(None)
        }
    }
}

