use serde_json::{Value, Map};

#[derive(Debug)]
enum Delta<'a> {
    Equal(&'a Value),
    BoolDifference(&'a Value, &'a Value),
    NumberDifference(&'a Value, &'a Value),
    StringDifference(&'a Value, &'a Value),
    ArrayDifference(&'a Value, &'a Value),
    ObjectDifference(&'a Value, &'a Value),
}

impl<'a> Delta<'a> {
    fn new(val1: &'a Value, val2: &'a Value) -> Delta<'a> {
        match (val1, val2) {
            (Value::Bool(b1), Value::Bool(b2)) if b1 == b2 => Delta::Equal(val1),
            (Value::Number(n1), Value::Number(n2)) if n1 == n2 => Delta::Equal(val1),
            (Value::String(s1), Value::String(s2)) if s1 == s2 => Delta::Equal(val1),
            (Value::Array(arr1), Value::Array(arr2)) if arr1 == arr2 => Delta::Equal(val1),
            (Value::Object(obj1), Value::Object(obj2)) if obj1 == obj2 => Delta::Equal(val1),
            (Value::Bool(_), Value::Bool(_)) => Delta::BoolDifference(val1, val2),
            (Value::Number(_), Value::Number(_)) => Delta::NumberDifference(val1, val2),
            (Value::String(_), Value::String(_)) => Delta::StringDifference(val1, val2),
            (Value::Array(_), Value::Array(_)) => Delta::ArrayDifference(val1, val2),
            (Value::Object(_), Value::Object(_)) => Delta::ObjectDifference(val1, val2),
            _ => panic!("Unsupported value types for comparison"),
        }
    }
}

/// Compare two JSON nodes and return their `Delta`.
fn compare_values<'a>(val1: &'a Value, val2: &'a Value) -> Delta<'a> {
    Delta::new(val1, val2)
}

fn main() {
    // Example usage
    let json1 = serde_json::json!({"name": "Alice", "age": 30});
    let json2 = serde_json::json!({"name": "Bob", "age": 25});
    let delta = compare_values(&json1, &json2);
    println!("{:?}", delta);
}
```

