use std::path::Path;
use std::path::PathBuf;
use std::fs;

pub fn list_all_files_with_ext<P: AsRef<Path>>(path: P, ext: &str) -> Vec<PathBuf> {
    let mut files_with_ext = Vec::new();
    if let Ok(entries) = fs::read_dir(path) {
        for entry in entries {
            if let Ok(entry) = entry {
                if let Some(file_name) = entry.file_name().to_str() {
                    if let Some(file_ext) = Path::new(file_name).extension() {
                        if file_ext == ext {
                            files_with_ext.push(entry.path());
                        }
                    }
                }
            }
        }
    }
    files_with_ext
}
```

In the solution, we use the `read_dir` function to obtain a directory iterator. For each entry in the iterator, we check if the file extension matches the specified extension. If it does, we add the file path to the `files_with_ext` vector. Finally, we return the vector containing the paths to files with the specified extension in the given directory.

