### Solution:
```rust
use std::time::{Instant, Duration};

struct Stopwatch {
    start_time: Option<Instant>,
    stop_time: Option<Instant>,
}

impl Stopwatch {
    fn new() -> Self {
        Stopwatch {
            start_time: None,
            stop_time: None,
        }
    }

    fn start(&mut self) {
        self.start_time = Some(Instant::now());
    }

    fn stop(&mut self) {
        self.stop_time = Some(Instant::now());
    }

    fn reset(&mut self) {
        self.start_time = None;
        self.stop_time = None;
    }

    fn elapsed_time(&self) -> Option<Duration> {
        match (self.start_time, self.stop_time) {
            (Some(start), Some(stop)) => Some(stop.duration_since(start)),
            _ => None,
        }
    }
}

fn main() {
    let mut stopwatch = Stopwatch::new();

    stopwatch.start();
    // Simulate some operation
    std::thread::sleep(Duration::from_secs(2));
    stopwatch.stop();

    if let Some(elapsed) = stopwatch.elapsed_time() {
        println!("Elapsed time: {} seconds", elapsed.as_secs());
    } else {
        println!("Stopwatch is still running");
    }

    stopwatch.reset();
}
```

