    case success(T)
    case failure(Error)
}

func fetchData(completionHandler: @escaping (Result<Data>) -> Void) {
    guard let url = URL(string: "https://example.com/data") else {
        let error = NSError(domain: "InvalidURL", code: 0, userInfo: [NSLocalizedDescriptionKey: "Invalid URL"])
        completionHandler(.failure(error))
