### Solution:
```rust
#[derive(Debug, PartialEq)]
enum Token {
    Identifier(String),
    Period,
    File,
}

fn lexer(input: &str) -> Vec<Token> {
    let mut tokens = Vec::new();
    let mut current_token = String::new();
    let mut chars = input.chars().peekable();

    while let Some(&c) = chars.peek() {
        if c.is_alphabetic() {
            while let Some(&c) = chars.peek() {
                if c.is_alphabetic() {
                    current_token.push(c);
                    chars.next();
                } else {
                    break;
                }
            }
            tokens.push(Token::Identifier(current_token.clone()));
            current_token.clear();
        } else if c == '.' {
            tokens.push(Token::Period);
            chars.next();
        } else if chars.as_str().starts_with("file") {
            tokens.push(Token::File);
            for _ in 0..4 {
                chars.next();
            }
        } else {
            // Handle other characters or raise an error for invalid input
            // For simplicity, let's assume that only valid input will be provided
        }
    }

    tokens
}

fn main() {
    let input = "hello.file";
    let tokens = lexer(input);
    for token in tokens {
        println!("{:?}", token);
    }
}
```

