#include <iostream>
#include <fstream>

void performOperation(int n, std::ofstream& output) {
    while (n != 1) {
        output << n << " ";
        if (n % 2 == 0) {
            n /= 2;
        } else {
            n = 3 * n + 1;
        }
    }
    output << "1" << std::endl << "Lie absolutely" << std::endl;
}

