```

You should implement the `countFiles` function to recursively count the number of files in the specified directory and its subdirectories. You can use the `opendir`, `readdir`, and `closedir` functions from the `dirent.h` header to traverse the directory structure.

### Solution:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <errno.h>

int countFiles(const char *path) {
    DIR *dir;
    struct dirent *entry;
    int count = 0;

    if ((dir = opendir(path)) != NULL) {
        while ((entry = readdir(dir)) != NULL) {
            if (entry->d_type == DT_REG) {
                count++;
            } else if (entry->d_type == DT_DIR && strcmp(entry->d_name, ".") != 0 && strcmp(entry->d_name, "..") != 0) {
                char subPath[1024];
                snprintf(subPath, sizeof(subPath), "%s/%s", path, entry->d_name);
                count += countFiles(subPath);
            }
        }
        closedir(dir);
    } else if (errno == ENOENT) {
        fprintf(stderr, "Error: Directory not found\n");
    } else {
        fprintf(stderr, "Error: Unable to open directory\n");
    }

    return count;
}

int main() {
    const char *directoryPath = "/path/to/directory";
    int totalFiles = countFiles(directoryPath);
    printf("Total files in directory: %d\n", totalFiles);
    return 0;
}
```

The `countFiles` function recursively traverses the directory structure, counting the number of regular files encountered. It uses the `opendir`, `readdir`, and `closedir` functions to navigate through the directory and its subdirectories. The function returns the total count of regular files found. If the directory cannot be opened or does not exist, appropriate error messages are printed to the standard error stream.

