### Solution:
```rust
pub fn tick_counter(&mut self) {
    // Check the reload flag
    if self.counter_reload {
        // If set, reload the linear counter with the counter period
        self.linear_counter = self.counter_period;
    } else if self.linear_counter > 0 {
        // If the counter is not set to reload and its value is greater than 0, decrement the counter by 1
