    // Your implementation here
}
```

### Solution:
```swift
func organizeFilesByExtension(sourceDirectory: String) {
    let fileManager = FileManager.default
    var isDirectory: ObjCBool = false

    // Check if the source directory exists
    if !fileManager.fileExists(atPath: sourceDirectory, isDirectory: &isDirectory) {
        // Create the source directory if it does not exist
        try? fileManager.createDirectory(atPath: sourceDirectory, withIntermediateDirectories: true, attributes: nil)
    }

    // Get the contents of the source directory
    if let contents = try? fileManager.contentsOfDirectory(atPath: sourceDirectory) {
        for file in contents {
            let filePath = sourceDirectory + "/" + file
            var isDirectory: ObjCBool = false

            // Check if the file is a directory
            if fileManager.fileExists(atPath: filePath, isDirectory: &isDirectory) && !isDirectory.boolValue {
                // Get the file extension
                let fileExtension = URL(fileURLWithPath: filePath).pathExtension

                // Create a subdirectory for the file extension if it does not exist
                let subDirectoryPath = sourceDirectory + "/" + fileExtension
                if !fileManager.fileExists(atPath: subDirectoryPath, isDirectory: &isDirectory) {
                    try? fileManager.createDirectory(atPath: subDirectoryPath, withIntermediateDirectories: true, attributes: nil)
                }

                // Move the file to the subdirectory
                let newFilePath = subDirectoryPath + "/" + file
                try? fileManager.moveItem(atPath: filePath, toPath: newFilePath)
            }
        }
    }
}
```

This solution first checks if the source directory exists and creates it if it does not. Then, it iterates through the files in the source directory, creates subdirectories for each file extension, and moves the files into their respective subdirectories. Any errors that occur during the file organization process are handled using Swift's error handling mechanism.

