// Define the ViewComponent enum representing different types of view components
enum ViewComponent {
    View(Box<ViewComponent>),
    // Other variants representing different types of view components
}

impl ViewComponent {
    // Method to collect all child widgets from the view component and its descendants
    fn collect_child_widgets(&self) -> Vec<Widget> {
        let mut widgets = Vec::new();
        match self {
            ViewComponent::View(subview) => {
                widgets.append(&mut subview.collect_child_widgets());
            }
            // Handle other variants if necessary
            _ => {}
        }
        widgets
    }
}
