func processSceneEvents(_ events: [String]) -> [String: [String: Int]] {
    var eventCounts: [String: [String: Int]] = [:]

    for event in events {
        let components = event.components(separatedBy: ",")
        if components.count == 2 {
            let eventType = components[0]
            let sceneName = components[1]

            if eventCounts[sceneName] == nil {
                eventCounts[sceneName] = [:]
