use std::str::FromStr;

impl FromStr for ListOp {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        if s.starts_with("Var(") && s.ends_with(")") {
            let index_str = &s[4..s.len() - 1];
            match index_str.parse::<usize>() {
                Ok(index) => Ok(ListOp::Var(index)),
                Err(_) => Err("Invalid index format".to_string()),
            }
        } else if s.starts_with("Ident(") && s.ends_with(")") {
            let ident = &s[6..s.len() - 1];
            if ident.contains(' ') {
                Err("Identifier cannot contain whitespace".to_string())
            } else {
                Ok(ListOp::Ident(ident.to_string()))
            }
        } else {
            Err("Invalid format".to_string())
        }
    }
}
```

The `FromStr` implementation first checks if the input string matches the format for `Var` or `Ident` operations. If it matches, it extracts the index or identifier and creates the corresponding enum variant. If the format is invalid or the index/identifier is in an incorrect format, appropriate error messages are returned.

